"""Fulfillment of orders into parcels ready for the carrier."""
from dataclasses import dataclass, field

from shopkit.shipping.packaging import weight_line


@dataclass(frozen=True)
class Item:
    sku: str
    qty: int


@dataclass(frozen=True)
class Parcel:
    order_id: str
    number: int
    items: tuple[tuple[str, int], ...] = field(default_factory=tuple)
    weight_g: int | None = None


def packing_slip(parcel: Parcel, chargeable_weight_g: int | None = None) -> str:
    lines = [f"Order {parcel.order_id} - parcel {parcel.number}"]
    weight = chargeable_weight_g if chargeable_weight_g is not None else parcel.weight_g
    if weight is not None:
        lines.append(weight_line(weight))
    lines += [f"  {qty} x {sku}" for sku, qty in parcel.items]
    return "\n".join(lines)
